INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-002', 'EG', 'P1', 'OPEN', NULL, NULL, 'RAMP GRADIENT HAS DOSE-RESPONSE EVIDENCE AND NO THRESHOLD. Batch 08 admitted two studies measuring the EFFECT of gradient (articular discomfort 14->36 percent across 0-4.8 deg; pushrim force 107N->230N across 3.5-15 deg) and none stating a value. Owner 2026-09-16: judgment may reason from effect to a range AS A PROXY. But both curves are monotonic with no reported plateau, so ''best outcome'' resolves to 0 deg, which is not a ramp. The determination needs a MAXIMUM ACCEPTABLE gradient, a threshold of acceptability, which no admitted source supplies. Closing this needs a code value or an equivalent criterion; see code lead 84 and candidate 68.', '2026-09-16 05:26', 'session_2026-09-16-research-batch-08-ramp-gradient', '2026-09-16 05:26', 'session_2026-09-16-research-batch-08-ramp-gradient', NULL, NULL, NULL, NULL, NULL);

