INSERT INTO "research_code_leads" ("lead_id", "jurisdiction", "standard_name", "clause", "status", "recovered_from", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (84, 'INT', 'Ramp gradient ceiling — retrieve the clause value', 'AS 1428.1:2021 s15 / BS 8300-1:2018 s10 / JIS T 9251:2014, ramp gradient', 'REFERENCE-ONLY', NULL, 'THE THRESHOLD HALF OF THE RAMP GRADIENT DETERMINATION. research_code_leads names which documents to fetch and deliberately holds no values (2026-08-12 REFERENCE-ONLY ruling), so the ceiling has to be retrieved rather than recalled. Needed because batch 08''s evidence is dose-response only: without a criterion of acceptability the proxy inference resolves to 0 degrees. Retrieve ONE jurisdiction''s ramp clause and the cell becomes determinable.', '2026-09-16 05:26', 'session_2026-09-16-research-batch-08-ramp-gradient', NULL, NULL);

