INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (68, 31, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'REF-00985 Marchiori 2023 FULL TEXT — confirm why the tested ceiling is 4.8 degrees', '10.3390/s23218659', NULL, 1, 0, 'Already admitted as REF-00985; this stages the FULL-TEXT pass, not a new source. The abstract gives only the range.', 'LEAD, NOT A FINDING: arctan(1/12) = 4.76 deg and 1:12 is the ramp ceiling in ADA, AS 1428.1 and BS 8300-1. If that is why 4.8 deg was chosen, the study measures discomfort across exactly the code-permitted range and is a CODE-INSUFFICIENCY finding under the owner ruling of 2026-09-13, not a bare dose-response curve. The abstract does not say this. Confirm against the full text before filing it as anything.', 'session_2026-09-16-research-batch-08-ramp-gradient', '2026-09-16 05:26');